-- Tasks indexes
CREATE INDEX idx_tasks_org_status ON tasks (organizationId, status);
CREATE INDEX idx_tasks_org_due ON tasks (organizationId, dueDate);
CREATE INDEX idx_tasks_venture ON tasks (ventureId);

-- Agent events indexes
CREATE INDEX idx_agent_events_org ON agent_events (organizationId, createdAt);
CREATE INDEX idx_agent_events_agent ON agent_events (agentName, createdAt);

-- SPVs indexes
CREATE INDEX idx_spvs_org ON spvs (organizationId, stage);

-- Distributions indexes
CREATE INDEX idx_distributions_org ON distributions (organizationId, status);

-- Org venture access indexes
CREATE INDEX idx_org_venture_org ON org_venture_access (organizationId);
CREATE INDEX idx_org_venture_venture ON org_venture_access (ventureId);

-- Invitations indexes
CREATE INDEX idx_invitations_org ON invitations (organizationId, inviteStatus);

-- Daily briefs, smart alerts, AI observations indexes
CREATE INDEX idx_daily_briefs_org ON daily_briefs (organizationId, createdAt);
CREATE INDEX idx_smart_alerts_org ON smart_alerts (organizationId, createdAt);
CREATE INDEX idx_ai_observations_org ON ai_observations (organizationId, createdAt);

-- Venture velocity indexes
CREATE INDEX idx_venture_velocity_org ON venture_velocity (organizationId, ventureId);

-- Contacts indexes
CREATE INDEX idx_contacts_org ON contacts (organizationId);

-- Audit log indexes
CREATE INDEX idx_audit_log_org ON audit_log (organizationId, timestamp);

